const PENCO={lat:-36.73194,lng:-72.9925},ESTACIONES={PUKEM:{nombre:"Pukem \xB7 Invierno",desc:"Las lluvias que purifican la tierra",color:"#4a6fa5"},PEWU:{nombre:"Pew\xFC \xB7 Primavera",desc:"El florecimiento y los nuevos brotes",color:"#7a9e7e"},WALUNG:{nombre:"Wal\xFCng \xB7 Verano",desc:"La abundancia y los d\xEDas largos",color:"#d4a947"},RIMU:{nombre:"Rim\xFC \xB7 Oto\xF1o",desc:"La cosecha guardada y el descanso",color:"#b06a4c"}},MOONS=[{n:1,nombre:"We Tripant\xFC K\xFCyen",traduccion:"Luna del a\xF1o nuevo",estacion:"PUKEM",descripcion:"Mar de invierno y marejadas frente a Penco y Lirqu\xE9n. Es tiempo de recogimiento: las primeras lluvias fuertes purifican la tierra tras el We Tripantu."},{n:2,nombre:"Llitun\xFCl Wilki K\xFCyen",traduccion:"Luna en que comienza el canto del zorzal",estacion:"PUKEM",descripcion:"Migraci\xF3n de ballenas frente a la costa del golfo de Arauco. Los d\xEDas m\xE1s cortos del a\xF1o quedan atr\xE1s y la luz empieza, apenas, a alargarse."},{n:3,nombre:"Llitun Pofpof An\xFCmka K\xFCyen",traduccion:"Luna en que brotan las semillas plantadas",estacion:"PUKEM",descripcion:"Primeros brotes en la vegetaci\xF3n de la cordillera de Nahuelbuta. El fr\xEDo cede terreno y la savia comienza a despertar en los \xE1rboles nativos."},{n:4,nombre:"Rayen Awar K\xFCyen",traduccion:"Luna en que florecen las habas",estacion:"PEWU",descripcion:"Floraci\xF3n de copihues y chilcos en los cerros de Penco. Pew\xFC, tiempo de florecimiento: la tierra se cubre de color despu\xE9s del invierno."},{n:5,nombre:"Longkon Kachilla K\xFCyen",traduccion:"Luna de las espigas",estacion:"PEWU",descripcion:"Llegada de aves migratorias a los humedales del B\xEDo-B\xEDo. La luz se alarga cada d\xEDa y el aire empieza a templarse sobre la bah\xEDa."},{n:6,nombre:"Kar\xFC Kachilla K\xFCyen",traduccion:"Luna del trigo verde",estacion:"PEWU",descripcion:"Inicio de la temporada de pesca artesanal en las caletas de la bah\xEDa de Concepci\xF3n. Se preparan las artes de pesca para los meses de mayor actividad."},{n:7,nombre:"Kudewall\xFCng K\xFCyen",traduccion:"Luna de las luci\xE9rnagas",estacion:"WALUNG",descripcion:"D\xEDas largos, apertura de playas en Penco y Rocuant. Comienza Wal\xFCng, tiempo de abundancia y de vida al aire libre junto al mar."},{n:8,nombre:"P\xFCramuw\xFCn Kachilla K\xFCyen \xB7 Are K\xFCyen",traduccion:"Luna de la cosecha \xB7 Luna del calor",estacion:"WALUNG",descripcion:"Pleno verano: m\xE1xima actividad costera, turismo y vida social en el borde mar. El sol se demora en irse tras la cordillera de la costa."},{n:9,nombre:"Tr\xFCntar\xFC K\xFCyen",traduccion:"Luna de las termitas",estacion:"WALUNG",descripcion:"Vendimia y cosecha en los valles interiores del B\xEDo-B\xEDo. El verano empieza a madurar hacia su fin, cargado de frutos."},{n:10,nombre:"Ng\xFClliw K\xFCyen",traduccion:"Luna de los pi\xF1ones",estacion:"RIMU",descripcion:"Cambio de color en los bosques nativos y primeras lluvias. Comienza Rim\xFC, tiempo de cosecha guardada, de recoger antes de que llegue el fr\xEDo."},{n:11,nombre:"Malli\xF1 Ko K\xFCyen",traduccion:"Luna del agua en los llanos",estacion:"RIMU",descripcion:"Recolecci\xF3n de pi\xF1ones y frutos del bosque en la precordillera. Es tiempo de guardar reservas y preparar la casa para el invierno."},{n:12,nombre:"Trangli\xF1 K\xFCyen",traduccion:"Luna de las heladas",estacion:"RIMU",descripcion:"Enfriamiento del mar y del aire sobre la bah\xEDa. La tierra se prepara para el descanso m\xE1s profundo del ciclo."},{n:13,nombre:"Maw\xFCn K\xFCr\xFCf K\xFCyen",traduccion:"Luna de la lluvia y el viento",estacion:"RIMU",descripcion:"Noches m\xE1s largas, cierre del ciclo. \xDAltima luna antes del D\xEDa Fuera del Tiempo y el regreso del sol en el nuevo We Tripantu."}],DFT={titulo:"El D\xEDa Fuera del Tiempo",texto1:"Despu\xE9s de la luna 13, queda un d\xEDa que no pertenece a ninguna cuenta: ni a esta luna ni a la siguiente. Es el d\xEDa en que el calendario se detiene un instante antes de reiniciar \u2014 un espacio fuera del tiempo administrado, dedicado al cierre, la memoria y la transici\xF3n hacia el nuevo ciclo.",sub2:"La v\xEDspera del We Tripantu",texto2:"En la tradici\xF3n mapuche, la noche que antecede al amanecer del nuevo ciclo se vive en vigilia. Las familias se re\xFAnen alrededor del fuego para compartir comida, conversaci\xF3n y relatos antiguos: un momento de fortalecimiento interno antes que una celebraci\xF3n p\xFAblica. Se comparten platos como mote, catutos, sopaipillas y muday, mientras se espera el amanecer.",texto3:"Al alba, antes de que salga el sol, muchas comunidades realizan un ba\xF1o ritual en un r\xEDo, estero o \u2014como ocurre en Talcahuano, al otro lado de esta misma bah\xEDa\u2014 en el mar: un gesto de purificaci\xF3n para dejar atr\xE1s lo viejo y recibir el nuevo ciclo renovados. Luego, mirando hacia el oriente, se agradece el ciclo que termina y se pide por el que comienza.",sub3:"C\xF3mo llevar esto a Penco",texto4:"Si puedes, cierra este d\xEDa junto al fuego o una vela, compartiendo una comida sencilla con quienes te acompa\xF1an.",texto5:"Al amanecer del d\xEDa siguiente, una caminata hasta la costa \u2014Penco, Lirqu\xE9n o Rocuant\u2014 puede ser tu propia versi\xF3n del gesto de renovaci\xF3n frente al mar.",texto6:"Usa el recuadro de abajo para mirar el ciclo completo: qu\xE9 cambi\xF3, qu\xE9 quieres soltar, qu\xE9 esperas del a\xF1o que comienza."},MOODS=[{e:"\u{1F60A}",c:"#7fbf5f",n:"Feliz"},{e:"\u{1F642}",c:"#b5d16b",n:"Tranquilo"},{e:"\u{1F610}",c:"#9aa3c7",n:"Neutral"},{e:"\u{1F634}",c:"#6a8fd8",n:"Cansado"},{e:"\u{1F622}",c:"#8a6fd8",n:"Triste"},{e:"\u{1F624}",c:"#e0913f",n:"Tenso"},{e:"\u{1F4AA}",c:"#d4a947",n:"Productivo"},{e:"\u{1F31F}",c:"#c96fb1",n:"Especial"},{e:"\u{1F60C}",c:"#8fd694",n:"Relajado"},{e:"\u{1F929}",c:"#f0d488",n:"Inspirado"},{e:"\u{1F64F}",c:"#d8a0ff",n:"Agradecido"},{e:"\u{1F60E}",c:"#7ab8ff",n:"Motivado"},{e:"\u{1F970}",c:"#f08ab0",n:"Cari\xF1oso"},{e:"\u{1F620}",c:"#e76e5a",n:"Enojado"},{e:"\u{1F630}",c:"#6aa8d8",n:"Ansioso"},{e:"\u{1F912}",c:"#9aa3c7",n:"Enfermo"}],EFEMERIDES={"01-01":"\u{1F389} A\xF1o Nuevo (feriado irrenunciable)","03-20":"Equinoccio de oto\xF1o","05-01":"\u{1F389} D\xEDa del Trabajo (feriado irrenunciable)","05-21":"\u{1F389} Glorias Navales","06-21":"We Tripantu \xB7 A\xF1o Nuevo Mapuche y solsticio de invierno + \u{1F389} D\xEDa Pueblos Ind\xEDgenas","06-29":"San Pedro \xB7 fiesta de los pescadores en las caletas + \u{1F389} San Pedro y San Pablo","07-16":"\u{1F389} Virgen del Carmen","08-15":"\u{1F389} Asunci\xF3n de la Virgen","09-18":"\u{1F389} Independencia Nacional (feriado irrenunciable)","09-19":"\u{1F389} Glorias del Ej\xE9rcito (feriado irrenunciable)","09-22":"Equinoccio de primavera","10-12":"\u{1F389} Encuentro de Dos Mundos","10-31":"\u{1F389} Iglesias Evang\xE9licas y Protestantes","11-01":"\u{1F389} Todos los Santos","12-08":"\u{1F389} Inmaculada Concepci\xF3n","12-21":"Solsticio de verano","12-25":"\u{1F389} Navidad (feriado irrenunciable)"},SIEMBRA={nueva:{fase:"\u{1F311} Luna Nueva",titulo:"Siembra de hojas y preparaci\xF3n",texto:"La savia baja hacia las ra\xEDces: buen momento para abonar, preparar la tierra y sembrar plantas de hoja.",siembra:"Lechuga, espinaca, acelga, perejil, cilantro, repollo.",tareas:"Abonar y mulchear \xB7 remover tierra \xB7 controlar malezas \xB7 evitar podar."},creciente:{fase:"\u{1F317} Cuarto Creciente",titulo:"Siembra de frutos y flores",texto:"La savia sube: es el mejor momento para sembrar y trasplantar lo que da fruto o flor.",siembra:"Tomate, poroto, zapallo, choclo, piment\xF3n, flores y hierbas arom\xE1ticas.",tareas:"Trasplantar \xB7 sembrar frutales \xB7 regar m\xE1s seguido \xB7 cosechar flores para secar."},llena:{fase:"\u{1F315} Luna Llena",titulo:"Cosecha de m\xE1xima savia",texto:"La planta est\xE1 en su punto m\xE1s alto de savia: ideal para cosechar hojas, frutos y hierbas medicinales.",siembra:"No sembrar: cosechar. Hierbas medicinales en plena ma\xF1ana.",tareas:"Cosechar hojas y frutos \xB7 elaborar conservas \xB7 fermentar \xB7 preparar tinturas."},menguante:{fase:"\u{1F313} Cuarto Menguante",titulo:"Ra\xEDces, poda y cuidado",texto:"La energ\xEDa vuelve a las ra\xEDces: tiempo de sembrar lo que crece bajo tierra, podar y prevenir plagas.",siembra:"Papa, zanahoria, betarraga, rabanito, ajo, cebolla.",tareas:"Podar \xE1rboles y arbustos \xB7 combatir plagas \xB7 cosechar ra\xEDces \xB7 abonar para el ciclo siguiente."}},SIEMBRA_LUNAS={1:{titulo:"Siembra de pleno invierno \u2014 guardar y preparar",epoca:"21 jun \u2013 18 jul \xB7 Pukem \xB7 lluvias y heladas",directa:"Haba, arveja, ajo chilote, cebolla, r\xE1bano, zanahoria temprana bajo t\xFAnel, lechuga de invierno, espinaca.",almacigos:"Ninguno a la intemperie; solo bajo cubierta: lechuga y acelga en alm\xE1cigo protegido.",cosecha:"\xDAltimas papas guardadas, manzanas de guarda, hierbas secas.",tareas:"Compostar y mulchear \xB7 podar frutales a ra\xEDz desnuda (manzano, cerezo) \xB7 preparar camas con guano \xB7 desmalezar y drenar."},2:{titulo:"Siembra de salida de invierno \u2014 alm\xE1cigos bajo techo",epoca:"19 jul \u2013 15 ago \xB7 Pukem \xB7 ballenas y luz que vuelve",directa:"Haba, arveja, espinaca, acelga, betarraga, zanahoria, lechuga, r\xE1bano, ajo, perejil, cilantro.",almacigos:"Tomate, pimiento, aj\xED, zapallo, albahaca, berenjena en invernadero o ventana luminosa.",cosecha:"Habas tempranas si hubo siembra oto\xF1al, hierbas perennes.",tareas:"Abonar y airear compost \xB7 plantar frutillas \xB7 limpiar acequias \xB7 proteger brotes de heladas tard\xEDas."},3:{titulo:"Fin de invierno \u2014 tierra que despierta",epoca:"16 ago \u2013 12 sep \xB7 Pukem \xB7 brotes en Nahuelbuta",directa:"Arveja, haba, lechuga, r\xFAcula, espinaca, betarraga, zanahoria, perejil, cilantro, r\xE1bano, cebolla.",almacigos:"Tomate, zapallo, poroto, ma\xEDz, albahaca, piment\xF3n.",cosecha:"Primeros rabanitos y lechugas de invierno.",tareas:"Trasplantar cebolla \xB7 preparar papas tempranas \xB7 abonar ligero \xB7 acolchar para retener humedad."},4:{titulo:"Equinoccio de primavera \u2014 plantar con fuerza",epoca:"13 sep \u2013 10 oct \xB7 Pew\xFC \xB7 copihues y chilcos",directa:"Poroto, ma\xEDz, zapallo, lechuga, acelga, zanahoria, betarraga, rabanito, perejil, cilantro, flores (cal\xE9ndula, cosmos).",almacigos:"Tomate, pimiento, pepino, albahaca, zapallo italiano.",cosecha:"Habas y arvejas en flor; hierbas para secar.",tareas:"Trasplantar tomates al exterior (tras heladas) \xB7 plantar papas \xB7 aporcar habas \xB7 riego moderado."},5:{titulo:"Primavera plena \u2014 crecimiento veloz",epoca:"11 oct \u2013 7 nov \xB7 Pew\xFC \xB7 aves migratorias",directa:"Poroto verde, ma\xEDz, zapallo italiano, pepino, lechuga, acelga, espinaca, betarraga, zanahoria, r\xE1bano, albahaca, girasol.",almacigos:"Tomate tard\xEDo, berenjena, piment\xF3n.",cosecha:"Primeras arvejas y habas tiernas; frutillas.",tareas:"Tutorar tomates \xB7 deshierbe frecuente \xB7 acolchar \xB7 cosechar flores para polinizadores."},6:{titulo:"Antesala del verano \u2014 riego y cuidado",epoca:"8 nov \u2013 5 dic \xB7 Pew\xFC \xB7 pesca artesanal",directa:"Poroto, ma\xEDz tard\xEDo, zapallo, pepino, lechuga de verano, r\xFAcula, betarraga, zanahoria, rabanito, albahaca.",almacigos:"Albahaca y flores de verano.",cosecha:"Habas y arvejas a granel, lechugas de primavera, frutillas, cerezas tempranas.",tareas:"Riego profundo y temprano \xB7 aporcar ma\xEDz y papas \xB7 plantar camote \xB7 cosechar semillas de haba."},7:{titulo:"Solsticio de verano \u2014 abundancia",epoca:"6 dic \u2013 2 ene \xB7 Wal\xFCng \xB7 playas abiertas",directa:"Poroto verde 2\xAA siembra, ma\xEDz, zapallo, lechuga de verano, albahaca, cilantro, rabanito, betarraga, perejil.",almacigos:"Repicado de albahaca y flores.",cosecha:"Tomate, pimiento, pepino, zapallito, papas tempranas, frutillas, ar\xE1ndanos, cerezas.",tareas:"Cosechar y conservar (salsa, mermelada) \xB7 guardar semillas \xB7 riego al atardecer \xB7 sombra a almacigos."},8:{titulo:"Pleno verano \u2014 cosechar y guardar",epoca:"3 \u2013 30 ene \xB7 Wal\xFCng \xB7 calor y costa",directa:"Lechuga, acelga, espinaca de verano, r\xE1bano, betarraga, zanahoria para oto\xF1o, cilantro.",almacigos:"Lechuga y acelga para oto\xF1o.",cosecha:"Tomate, pimiento, choclo, poroto verde, zapallo italiano, berries, duraznos, ciruelas.",tareas:"Cosecha diaria \xB7 secar hierbas \xB7 feriar e intercambiar \xB7 preparar alm\xE1cigos oto\xF1ales bajo malla."},9:{titulo:"Cierre de verano \u2014 segunda oportunidad",epoca:"31 ene \u2013 27 feb \xB7 Wal\xFCng \xB7 vendimia",directa:"Lechuga, espinaca, acelga, betarraga, zanahoria, r\xE1bano, haba temprana, arveja oto\xF1al, br\xF3coli, coliflor.",almacigos:"Br\xF3coli, coliflor, repollo para oto\xF1o-invierno.",cosecha:"Tomates tard\xEDos, zapallos de guarda, choclos, pimientos, uvas, manzanas tempranas.",tareas:"Conservar y fermentar \xB7 guardar semillas de tomate y zapallo \xB7 plantar frutillas nuevas."},10:{titulo:"Inicio de oto\xF1o \u2014 guardar para el fr\xEDo",epoca:"28 feb \u2013 27 mar \xB7 Rim\xFC \xB7 bosques que cambian",directa:"Haba, arveja, lechuga oto\xF1al, espinaca, acelga, betarraga, zanahoria, r\xE1bano, repollo, br\xF3coli, coliflor, ajo, cebolla.",almacigos:"Habas y arvejas directo es mejor que alm\xE1cigo.",cosecha:"Zapallos de guarda, ma\xEDz para choclo seco, porotos granados, manzanas, membrillos, nueces.",tareas:"Cosechar y almacenar papas \xB7 compostar hojas \xB7 trasplantar frutillas \xB7 sembrar abono verde (avena/vicia)."},11:{titulo:"Oto\xF1o medio \u2014 pi\xF1ones y reservas",epoca:"28 mar \u2013 24 abr \xB7 Rim\xFC \xB7 recolecci\xF3n en precordillera",directa:"Ajo, cebolla, haba, arveja, lechuga, espinaca, acelga, rabanito, betarraga, zanahoria, repollo, br\xF3coli.",almacigos:"Ajo chilote en surco profundo.",cosecha:"Pi\xF1ones (ng\xFClliw), avellanas, manzanas tard\xEDas, membrillos; hongos de pino.",tareas:"Recolectar pi\xF1ones \xB7 plantar frutales \xB7 acolchar con hojas \xB7 guardar le\xF1a y conservas."},12:{titulo:"Oto\xF1o tard\xEDo \u2014 heladas que se acercan",epoca:"25 abr \u2013 22 may \xB7 Rim\xFC \xB7 mar que se enfr\xEDa",directa:"Ajo, haba, arveja, lechuga bajo t\xFAnel, espinaca, r\xE1bano, cilantro, perejil, ciboulette.",almacigos:"Ajos en luna menguante; habas y arvejas directo.",cosecha:"\xDAltimos pi\xF1ones, nueces, membrillos; hierbas para secar antes de heladas.",tareas:"Plantar ajos \xB7 levantar camas con compost \xB7 preparar invernadero \xB7 podar hojas secas."},13:{titulo:"Antes del nuevo sol \u2014 descanso de la tierra",epoca:"23 may \u2013 19 jun \xB7 Rim\xFC \xB7 noches m\xE1s largas",directa:"Ajo, haba, arveja, lechuga de invierno, espinaca, r\xE1bano bajo cubierta.",almacigos:"Solo bajo cubierta: lechuga, acelga.",cosecha:"Pi\xF1ones finales, nueces, hierbas secas; nada m\xE1s hasta el nuevo ciclo.",tareas:"Abonar con compost maduro \xB7 podar frutales \xB7 planificar rotaci\xF3n \xB7 descanso, memoria y preparaci\xF3n para We Tripantu."}},INTRO={titulo:"CALENDARIO DE LAS 13 LUNAS",subtitulo:"Mari K\xFCla K\xFCyen",lugar:"Golfo de Arauco \xB7 Penco, B\xEDo-B\xEDo, Chile"},DONATE={flow:"",mercadopago:"",paypal:"",kofi:""},AVES_PENCO=[{nombre:"Gaviota dominicana",cient:"Larus dominicanus",hab:"Costa, playa, bah\xEDa",icon:"\u{1F54A}\uFE0F",epoca:"Todo el a\xF1o"},{nombre:"Zarapito",cient:"Numenius phaeopus",hab:"Humedal Rocuant, orilla",icon:"\u{1F9A9}",epoca:"Sep \u2013 Mar (migratoria)"},{nombre:"Pilpil\xE9n",cient:"Haematopus palliatus",hab:"Playa, roquer\xEDos",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Garza cuca",cient:"Ardea cocoi",hab:"Humedal, estero Penco",icon:"\u{1F9A2}",epoca:"Todo el a\xF1o"},{nombre:"Cisne coscoroba",cient:"Coscoroba coscoroba",hab:"Humedal Rocuant",icon:"\u{1F9A2}",epoca:"Invierno-primavera"},{nombre:"Trabajador",cient:"Phleocryptes melanops",hab:"Totora, humedal",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Loica",cient:"Leistes loyca",hab:"Pradera, borde cerro",icon:"\u{1F426}",epoca:"Todo el a\xF1o \u2013 canto primavera"},{nombre:"Chorlo nevado",cient:"Charadrius nivosus",hab:"Playa, duna",icon:"\u{1F427}",epoca:"Oct \u2013 Feb (nidifica)"},{nombre:"Yeco / Cormor\xE1n",cient:"Phalacrocorax brasilianus",hab:"Rocas, muelle Lirqu\xE9n",icon:"\u{1F985}",epoca:"Todo el a\xF1o"},{nombre:"Pato jerg\xF3n",cient:"Anas georgica",hab:"Humedal, laguna",icon:"\u{1F986}",epoca:"Todo el a\xF1o"},{nombre:"F\xEDo-f\xEDo",cient:"Elaenia albiceps",hab:"Matorral, bosque",icon:"\u{1F426}",epoca:"Sep \u2013 Mar"},{nombre:"Zorzal",cient:"Turdus falcklandii",hab:"Jard\xEDn, bosque",icon:"\u{1F426}",epoca:"Todo el a\xF1o \u2013 canto invierno"},{nombre:"Bandurria",cient:"Theristicus melanopis",hab:"Pradera, humedal",icon:"\u{1F9A9}",epoca:"Todo el a\xF1o"},{nombre:"Queltrehue / Treile",cient:"Vanellus chilensis",hab:"Pastizal, cancha",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Picaflor chico",cient:"Sephanoides sephaniodes",hab:"Jard\xEDn, bosque",icon:"\u{1F41D}",epoca:"Sep \u2013 Abr"},{nombre:"Conc\xF3n",cient:"Strix rufipes",hab:"Bosque nativo",icon:"\u{1F989}",epoca:"Todo el a\xF1o \u2013 nocturna"},{nombre:"Tenca",cient:"Mimus thenca",hab:"Matorral, bosque escler\xF3filo, jard\xEDn",icon:"\u{1F426}",epoca:"Todo el a\xF1o \u2013 canto primavera"},{nombre:"Diuca",cient:"Diuca diuca",hab:"Pradera, borde bosque, cerco",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Chucao",cient:"Scelorchilus rubecula",hab:"Sotobosque h\xFAmedo, quebrada, quila",icon:"\u{1F426}",epoca:"Todo el a\xF1o \u2013 canto lluvia"},{nombre:"Cherc\xE1n",cient:"Troglodytes aedon",hab:"Jard\xEDn, sotobosque, cerco vivo",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Rayadito",cient:"Aphrastura spinicauda",hab:"Bosque nativo, canelo-array\xE1n",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Cachudito",cient:"Anairetes parulus",hab:"Matorral, bosque bajo, maqui",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Torcaza",cient:"Patagioenas araucana",hab:"Bosque nativo, peumo-boldo",icon:"\u{1F54A}\uFE0F",epoca:"Todo el a\xF1o \u2013 bandadas oto\xF1o"},{nombre:"Carpintero chico",cient:"Veniliornis lignarius",hab:"Bosque nativo, troncos viejos",icon:"\u{1F426}",epoca:"Todo el a\xF1o"},{nombre:"Cometocino",cient:"Phrygilus patagonicus",hab:"Sotobosque, borde bosque",icon:"\u{1F426}",epoca:"Oto\xF1o-invierno"},{nombre:"Jilguero",cient:"Spinus barbatus",hab:"Bosque, pradera, quillay-mait\xE9n",icon:"\u{1F426}",epoca:"Todo el a\xF1o"}],EVENTOS_ASTRONOMICOS=[{date:"2026-02-17",tipo:"eclipse",icon:"\u{1F318}",nombre:"Eclipse anular de Sol",desc:"Ant\xE1rtida / sur. Desde Penco parcial muy bajo. No mirar directo."},{date:"2026-03-03",tipo:"eclipse",icon:"\u{1F315}",nombre:"Eclipse total de Luna",desc:"Visible en Chile madrugada. Luna roja ~3:00\u20134:30 CL."},{date:"2026-03-20",tipo:"equinoccio",icon:"\u{1F342}",nombre:"Equinoccio de oto\xF1o",desc:"Inicio oto\xF1o sur. Sol cruza ecuador."},{date:"2026-06-21",tipo:"solsticio",icon:"\u2744\uFE0F",nombre:"Solsticio de invierno + We Tripantu",desc:"D\xEDa m\xE1s corto. A\xF1o nuevo mapuche."},{date:"2026-08-12",tipo:"eclipse",icon:"\u{1F318}",nombre:"Eclipse total de Sol (\xC1rtico/Europa)",desc:"No visible en Chile. Lo listamos para referencia."},{date:"2026-08-28",tipo:"eclipse",icon:"\u{1F315}",nombre:"Eclipse parcial de Luna",desc:"Visible en Chile al amanecer. Parte norte."},{date:"2026-09-22",tipo:"equinoccio",icon:"\u{1F338}",nombre:"Equinoccio de primavera",desc:"Inicio primavera sur."},{date:"2026-12-21",tipo:"solsticio",icon:"\u2600\uFE0F",nombre:"Solsticio de verano",desc:"D\xEDa m\xE1s largo."},{date:"2026-11-24",tipo:"superluna",icon:"\u{1F315}",nombre:"Superluna (perigeo)",desc:"Luna llena m\xE1s grande. Marea m\xE1s alta."},{date:"2026-12-24",tipo:"superluna",icon:"\u{1F315}",nombre:"Superluna fr\xEDa",desc:"\xDAltima llena del a\xF1o, perigeo."},{date:"2026-01-03",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Cuadr\xE1ntidas (pico)",desc:"Hasta 40 met/h. Mejor 03:00-06:00."},{date:"2026-04-22",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"L\xEDridas (pico)",desc:"10-15 met/h. Madrugada."},{date:"2026-05-06",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Eta Acu\xE1ridas (pico)",desc:"Restos cometa Halley. Sur ideal 30 met/h."},{date:"2026-08-12",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Perseidas (pico)",desc:"50 met/h. Mejor norte, pero visible."},{date:"2026-10-21",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Ori\xF3nidas (pico)",desc:"Halley otra vez. 15 met/h."},{date:"2026-11-17",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Le\xF3nidas (pico)",desc:"10 met/h, b\xF3lidos."},{date:"2026-12-14",tipo:"lluvia",icon:"\u2604\uFE0F",nombre:"Gem\xEDnidas (pico)",desc:"Mejor del a\xF1o 120 met/h. Madrugada."},{date:"2027-02-06",tipo:"eclipse",icon:"\u{1F318}",nombre:"Eclipse anular de Sol",desc:"\xC1frica/Sur Am\xE9rica. Parcial en sur Chile tarde."},{date:"2027-08-02",tipo:"eclipse",icon:"\u{1F318}",nombre:"Eclipse total de Sol",desc:"Norte \xC1frica/Espa\xF1a. No visible Chile."}],EVENTOS_COMUNA_PENCO=[{md:"02-12",nombre:"Aniversario fundaci\xF3n de Penco",icon:"\u{1F3DB}\uFE0F",desc:"1550 fundaci\xF3n de Concepci\xF3n en Penco. Actos municipales, desfile",cat:"municipal"},{md:"02-14",nombre:"Carnaval de Penco \u2014 Playa",icon:"\u{1F3AD}",desc:"M\xFAsica, comparsas en costanera. Fecha m\xF3vil feb",cat:"fiesta"},{md:"03-08",nombre:"D\xEDa de la Mujer \u2014 Feria Rocuant",icon:"\u{1F49C}",desc:"Feria de emprendedoras, humedal",cat:"cultura"},{md:"05-21",nombre:"Glorias Navales \u2014 desfile",icon:"\u2693",desc:"Escuelas y Armada en plaza",cat:"municipal"},{md:"06-21",nombre:"We Tripantu comunal",icon:"\u{1F33F}",desc:"Rogativa al amanecer en playa/borde r\xEDo",cat:"cultura"},{md:"06-29",nombre:"Fiesta de San Pedro \u2014 Caleta Lirqu\xE9n",icon:"\u{1F41F}",desc:"Patrono pescadores. Misa, procesi\xF3n a mar",cat:"religioso"},{md:"07-26",nombre:"Santa Ana \u2014 patrona Penco",icon:"\u26EA",desc:"Fiesta religiosa local, feria",cat:"religioso"},{md:"08-15",nombre:"Feria costumbrista invierno",icon:"\u{1F958}",desc:"Gastronom\xEDa, chupalla, artesan\xEDa",cat:"feria"},{md:"09-18",nombre:"Fiestas Patrias \u2014 ramadas Penco",icon:"\u{1F1E8}\u{1F1F1}",desc:"18-19 ramadas en estadio/costanera",cat:"fiesta"},{md:"10-12",nombre:"Aniversario Cuerpo Bomberos Penco",icon:"\u{1F692}",desc:"Desfile, ejercicio",cat:"municipal"},{md:"11-01",nombre:"Noche de las velas \u2014 cementerio",icon:"\u{1F56F}\uFE0F",desc:"Tradici\xF3n familiar",cat:"cultura"},{md:"12-08",nombre:"Virgen de la Candelaria \u2014 Lirqu\xE9n",icon:"\u{1F64F}",desc:"Procesi\xF3n",cat:"religioso"},{md:"12-31",nombre:"A\xF1o Nuevo en playa \u2014 show pirotecnia",icon:"\u{1F386}",desc:"Costanera Penco, m\xFAsica",cat:"fiesta"},{md:"01-01",nombre:"A\xF1o Nuevo \u2014 feria amanecida",icon:"\u{1F389}",desc:"Feria madrugada 1 ene",cat:"feria"}],ASOCIACIONES_CULTIVOS=[{cultivo:"Tomate",icono:"\u{1F345}",familia:"Solan\xE1cea",buenas:["Albahaca","Zanahoria","Perejil","Lechuga","Ajo","Cebolla"],malas:["Repollo","Coliflor","Hinojo","Papa"],nota:"Albahaca repele mosca blanca y pulg\xF3n; no junto a repollo compite por nutrientes. 40-60 cm entre plantas."},{cultivo:"Lechuga",icono:"\u{1F96C}",familia:"Aster\xE1cea",buenas:["Rabanito","Zanahoria","Frutilla","Pepino","Cebolla","Betarraga"],malas:["Perejil","Apio"],nota:"Rabanito marca hileras y se cosecha antes; buena entre tomates para sombra parcial."},{cultivo:"Zanahoria",icono:"\u{1F955}",familia:"Api\xE1cea",buenas:["Cebolla","Ajo","Lechuga","Tomate","Arveja","R\xE1bano"],malas:["Eneldo","Perejil en exceso"],nota:"Cebolla/ajo confunden mosca de la zanahoria. Siembra rala, intercala con lechuga."},{cultivo:"Cebolla",icono:"\u{1F9C5}",familia:"Amarilid\xE1cea",buenas:["Zanahoria","Lechuga","Betarraga","Frutilla","Manzanilla"],malas:["Arveja","Poroto","Haba"],nota:"Repele pulg\xF3n y mosca. No con leguminosas (inhibe crecimiento)."},{cultivo:"Ajo chilote",icono:"\u{1F9C4}",familia:"Amarilid\xE1cea",buenas:["Frutilla","Lechuga","Zanahoria","Tomate","Betarraga"],malas:["Arveja","Poroto","Repollo"],nota:"Fungicida natural. Plantar en borde de bancal en menguante."},{cultivo:"Haba",icono:"\u{1FAD8}",familia:"Leguminosa",buenas:["Ma\xEDz","Papa","Acelga","Lechuga","Zanahoria"],malas:["Cebolla","Ajo","Puerro"],nota:"Fija nitr\xF3geno. Ideal como abono verde antes de ma\xEDz/tomate. Tutorar si viento."},{cultivo:"Arveja",icono:"\u{1F7E2}",familia:"Leguminosa",buenas:["Zanahoria","R\xE1bano","Ma\xEDz","Pepino","Lechuga"],malas:["Cebolla","Ajo","Papa"],nota:"Enramar 1,5 m. Cosecha escalonada; deja ra\xEDces para fertilizar."},{cultivo:"Poroto / Frijol",icono:"\u{1FAD8}",familia:"Leguminosa",buenas:["Ma\xEDz","Zapallo","R\xE1bano","Zanahoria","Albahaca"],malas:["Cebolla","Ajo","Hinojo"],nota:"Milpa: ma\xEDz tutor + zapallo cubre suelo. No con cebolla."},{cultivo:"Ma\xEDz / Choclo",icono:"\u{1F33D}",familia:"Gram\xEDnea",buenas:["Poroto","Zapallo","Arveja","Papa","Pepino"],malas:["Betarraga"],nota:"Tres hermanas mapuche: ma\xEDz + poroto + zapallo. Deja ca\xF1as para tutor de poroto."},{cultivo:"Zapallo / Calabaza",icono:"\u{1F383}",familia:"Cucurbit\xE1cea",buenas:["Ma\xEDz","Poroto","R\xE1bano","Manzanilla"],malas:["Papa","Zapallo italiano juntos"],nota:"Rastrero tapa suelo y conserva humedad. Separar 1,2 m. Flores atraen polinizadores."},{cultivo:"Zapallo italiano",icono:"\u{1F952}",familia:"Cucurbit\xE1cea",buenas:["Ma\xEDz","Poroto","Albahaca","Lechuga"],malas:["Papa"],nota:"Cosecha tierno cada 3 d\xEDas para seguir produciendo."},{cultivo:"Pepino",icono:"\u{1F952}",familia:"Cucurbit\xE1cea",buenas:["Ma\xEDz","Arveja","Lechuga","Girasol","Ajo"],malas:["Papa","Tomate muy cerca"],nota:"Gu\xEDa vertical mejora aireaci\xF3n. Con girasol atrae abejas."},{cultivo:"Pimiento / Aj\xED",icono:"\u{1FAD1}",familia:"Solan\xE1cea",buenas:["Albahaca","Zanahoria","Espinaca","Ajo"],malas:["Repollo","Hinojo"],nota:"Misma familia que tomate, mismas asociaciones. Protege de viento sur."},{cultivo:"Papa",icono:"\u{1F954}",familia:"Solan\xE1cea",buenas:["Haba","Ma\xEDz","Ajo","R\xE1bano","Repollo"],malas:["Tomate","Zapallo","Pepino","Cebolla"],nota:"No junto a tomate (tiz\xF3n). Ap\xF3rcar tierra 2 veces."},{cultivo:"Betarraga",icono:"\u{1F7E3}",familia:"Amarant\xE1cea",buenas:["Lechuga","Cebolla","Ajo","Repollo","Acelga"],malas:["Poroto","Ma\xEDz"],nota:"Afloja suelo arcilloso de Penco. Raleo a 8 cm."},{cultivo:"Espinaca",icono:"\u{1F33F}",familia:"Amarant\xE1cea",buenas:["Frutilla","R\xE1bano","Lechuga","Poroto","Cebolla"],malas:["Betarraga muy densa"],nota:"Sombra parcial en verano. Siembra escalonada cada 20 d\xEDas."},{cultivo:"Acelga",icono:"\u{1F96C}",familia:"Amarant\xE1cea",buenas:["Lechuga","Cebolla","Ajo","R\xE1bano","Haba"],malas:["Perejil"],nota:"Corte hoja a hoja, dura 8 meses. Muy r\xFAstica para Penco."},{cultivo:"Repollo / Col",icono:"\u{1F96C}",familia:"Brasic\xE1cea",buenas:["Papa","Betarraga","Manzanilla","Eneldo","Cebolla"],malas:["Tomate","Frutilla","Ajo en exceso"],nota:"Manzanilla mejora sabor y repele polilla. Rotar cada 3 a\xF1os."},{cultivo:"Br\xF3coli / Coliflor",icono:"\u{1F966}",familia:"Brasic\xE1cea",buenas:["Papa","Cebolla","Manzanilla","Lechuga","Betarraga"],malas:["Frutilla","Tomate"],nota:"Exigente en compost. Cosecha antes que abra flor."},{cultivo:"R\xE1bano",icono:"\u{1F534}",familia:"Brasic\xE1cea",buenas:["Lechuga","Zanahoria","Espinaca","Arveja","Pepino"],malas:["Haba densa"],nota:"Ciclo 25 d\xEDas, ideal para marcar hileras de zanahoria. No en sombra."},{cultivo:"Albahaca",icono:"\u{1F331}",familia:"Lami\xE1cea",buenas:["Tomate","Pimiento","Lechuga","Frutilla"],malas:["Salvia cerca"],nota:"Repelente estrella. Intercalar 1 cada 4 tomates. Cosecha puntas para ramificar."},{cultivo:"Frutilla",icono:"\u{1F353}",familia:"Ros\xE1cea",buenas:["Ajo","Lechuga","Espinaca","Cebolla","Betarraga"],malas:["Repollo","Papa"],nota:"Ajo entre frutillas reduce botritis. Mulch de paja, renovar cada 3 a\xF1os."},{cultivo:"Perejil / Cilantro",icono:"\u{1F33F}",familia:"Api\xE1cea",buenas:["Tomate","Ma\xEDz","Esp\xE1rrago"],malas:["Lechuga en exceso"],nota:"Atrae s\xEDrfidos (comen pulg\xF3n). Dejar florecer una planta para semillas."}],PREPARADOS_ORGANICOS=[{nombre:"Pur\xEDn de ortiga",icono:"\u{1F33F}",tipo:"Biofertilizante + repelente",familia:"Fertilizante",ingredientes:"1 kg ortiga fresca sin flor + 10 L agua de lluvia",preparacion:"Picar ortiga, cubrir con agua en balde pl\xE1stico (no metal), remover diario 10-14 d\xEDas hasta que no haga espuma. Filtrar. Conserva 2-3 semanas a la sombra.",dosis:"Fertilizante: 1:10 (1 L pur\xEDn /10 L agua) riego cada 14 d\xEDas \xB7 Foliar repelente pulg\xF3n: 1:20 cada 7 d\xEDas",uso:"Pew\xFC-Wal\xFCng. Estimula crecimiento y repele pulg\xF3n. No usar puro (quema).",luna:"Creciente",precauciones:"Olor fuerte, usa guantes. No en interior. No sobre flores abiertas."},{nombre:"Pur\xEDn de cola de caballo",icono:"\u{1F33E}",tipo:"Fungicida preventivo",familia:"Fungicida",ingredientes:"100 g cola de caballo seca + 1 L agua (o 1 kg fresca /10 L)",preparacion:"Hervir 30 min, reposar 12 h, filtrar. Dura 2 semanas refrigerado. Tambi\xE9n se hace fermentado 10 d\xEDas como ortiga.",dosis:"Preventivo: 1:5 cada 10-14 d\xEDas. Curativo suave: 1:3 cada 7 d\xEDas",uso:"Pukem-Rim\xFC. Previene o\xEDdio, mildiu, roya, botritis por s\xEDlice. Ideal en tomate, cucurbit\xE1ceas, frutilla.",luna:"Menguante",precauciones:"Aplicar ma\xF1ana sin sol fuerte. No mezclar con cobre el mismo d\xEDa."},{nombre:"Caldo bordel\xE9s",icono:"\u{1F535}",tipo:"Fungicida c\xFAprico",familia:"Fungicida",ingredientes:"100 g sulfato de cobre + 100 g cal viva + 10 L agua (1%)",preparacion:"Disolver cobre en 5 L agua tibia. Apagar cal en 5 L aparte. Verter cobre sobre cal (nunca al rev\xE9s) removiendo. Probar con clavo: si no se oxida, est\xE1 neutro.",dosis:"1% (100 g/10 L) cada 15-21 d\xEDas. M\xE1x 3-4 aplicaciones por ciclo. Suspender 15 d\xEDas antes de cosecha.",uso:"Previene tiz\xF3n tomate/papa, mildiu. Pukem y Rim\xFC lluviosos.",luna:"Menguante",precauciones:"Cobre se acumula en suelo. Usa mascarilla/guantes. No aplicar con sol >28\xB0C. No en floraci\xF3n intensa."},{nombre:"Caldo sulfoc\xE1lcico",icono:"\u{1F7E1}",tipo:"Fungicida + acaricida",familia:"Fungicida",ingredientes:"1 kg azufre + 500 g cal viva + 5 L agua",preparacion:"Hervir agua, agregar azufre y cal removiendo 45-60 min hasta color vino tinto. Reposar, filtrar. Guarda oscuro hasta 3 meses.",dosis:"Invierno: 1:10. Verano: 1:25 a 1:40 (prueba en 1 rama). Cada 15 d\xEDas.",uso:"O\xEDdio, ara\xF1ita roja, cochinilla en frutales y tomates. Aplica tarde nublada.",luna:"Menguante",precauciones:"No mezclar con aceite/neem el mismo mes. Corrosivo: guantes/lentes. No en cucurbit\xE1ceas con fruto peque\xF1o."},{nombre:"Jab\xF3n pot\xE1sico",icono:"\u{1F9FC}",tipo:"Insecticida suave",familia:"Insecticida",ingredientes:"20 g jab\xF3n pot\xE1sico puro (o jab\xF3n Popeye sin perfume rallado) + 1 L agua tibia",preparacion:"Disolver bien. Si usas pot\xE1sico l\xEDquido: 10-15 ml/L. Preparar al momento. A\xF1adir 10 ml aceite vegetal por litro para adherencia (opcional).",dosis:"10-20 g/L. Pulveriza cubriendo env\xE9s de hojas cada 5-7 d\xEDas, 3 aplicaciones.",uso:"Pulg\xF3n, mosca blanca, cochinilla, ara\xF1ita. Pew\xFC-Wal\xFCng. Ideal con tomate, lechuga, br\xF3coli.",luna:"Cualquiera, tarde",precauciones:"No con sol directo (quema). Prueba en 1 hoja. No mezclar con azufre/cobre el mismo d\xEDa."},{nombre:"Aceite de neem",icono:"\u{1F333}",tipo:"Insecticida + repelente",familia:"Insecticida",ingredientes:"5 ml aceite de neem prensado en fr\xEDo + 2 ml jab\xF3n pot\xE1sico + 1 L agua tibia",preparacion:"Emulsionar neem con jab\xF3n en poca agua tibia, luego completar a 1 L. Agitar constante durante aplicaci\xF3n. Preparar al momento.",dosis:"3-5 ml/L cada 7-10 d\xEDas. Preventivo cada 14 d\xEDas.",uso:"Repele y corta muda de pulg\xF3n, polilla, mosca blanca, trips. Val en casi todo huerto.",luna:"Menguante/noche",precauciones:"Aplicar atardecer (se degrada con sol). No en flor abierta (afecta abejas). Intervalo 7 d\xEDas antes de cosecha."},{nombre:"Biopreparado ajo-aj\xED",icono:"\u{1F9C4}\u{1F336}\uFE0F",tipo:"Repelente amplio",familia:"Insecticida",ingredientes:"3 cabezas ajo + 3 aj\xEDes + 1 L agua + 10 ml jab\xF3n pot\xE1sico",preparacion:"Licuar ajo+aj\xED con agua, macerar 24 h tapado, filtrar con tela, agregar jab\xF3n. Dura 7 d\xEDas refrigerado.",dosis:"50 ml /L cada 7 d\xEDas. Refuerzo diario si ataque leve.",uso:"Repele pulg\xF3n, orugas, babosas. Muy usado en Penco para haba y repollo.",luna:"Menguante",precauciones:"Pica: usa guantes/lentes. No en d\xEDas de cosecha. Lavar bien hortalizas."},{nombre:"Trampa + cebo babosas (cerveza/ceniza)",icono:"\u{1F40C}",tipo:"Trampa f\xEDsica",familia:"Trampa",ingredientes:"Vasos enterrados + cerveza o levadura + agua + ceniza de le\xF1a",preparacion:"Enterrar vaso a ras suelo, llenar 2/3 con cerveza. Rodear bancal con anillo de ceniza seca de 3 cm. Revisar cada ma\xF1ana.",dosis:"3-4 vasos por bancal. Renovar cada 2 d\xEDas.",uso:"Pukem-Rim\xFC. Babosas y caracoles en lechuga, frutilla, haba.",luna:"Nueva",precauciones:"Ceniza no sobre plantines (alcaliniza). No usar sal (da\xF1a suelo)."},{nombre:"T\xE9 de compost / humus l\xEDquido",icono:"\u{1FAB1}",tipo:"Biofertilizante",familia:"Fertilizante",ingredientes:"1 kg compost maduro o humus + 10 L agua + 20 g az\xFAcar/panela",preparacion:"Bolsa de tela con compost en balde con agua, airear con burbujeo 24-36 h (o remover 3x d\xEDa). Filtrar. Usar en 24 h.",dosis:"Riego: puro o 1:3. Foliar: 1:10 cada 14 d\xEDas.",uso:"Activa microvida, mejora suelo arcilloso de Penco. Todo el a\xF1o, mejor Pew\xFC.",luna:"Creciente",precauciones:"Usar compost bien maduro (sin olor feo). No almacenar m\xE1s de 1 d\xEDa (anaerobio)."},{nombre:"Bocashi r\xE1pido",icono:"\u267B\uFE0F",tipo:"Abono fermentado",familia:"Fertilizante",ingredientes:"10 kg guano seco + 10 kg tierra + 5 kg afrechillo + 1 kg carb\xF3n molido + levadura + chancaca + agua",preparacion:"Mezclar secos, disolver 10 g levadura + 200 g chancaca en 5 L agua tibia, humedecer hasta pu\xF1o h\xFAmedo. Pila 50 cm, voltear 2x d\xEDa 7-14 d\xEDas hasta que baje temperatura.",dosis:"500 g/m\xB2 incorporaci\xF3n 7 d\xEDas antes de siembra. Mantenci\xF3n: 100 g/planta cada 30 d\xEDas.",uso:"Suelo pobre o arcilloso. Prepara 2 semanas antes de luna ideal de siembra.",luna:"Menguante (preparaci\xF3n)",precauciones:"No aplicar fresco (quema). Secar y guardar saco a la sombra."},{nombre:"Pur\xEDn de ortiga + consuelda (pot\xE1sico)",icono:"\u{1F34C}",tipo:"Pot\xE1sico floraci\xF3n",familia:"Fertilizante",ingredientes:"500 g ortiga + 500 g consuelda + c\xE1scaras pl\xE1tano + 10 L agua",preparacion:"Fermentar igual que pur\xEDn ortiga 14 d\xEDas. C\xE1scaras aportan potasio.",dosis:"1:10 cada 14 d\xEDas en floraci\xF3n/fructificaci\xF3n.",uso:"Tomate, pimiento, frutilla en Wal\xFCng para cuaje y sabor.",luna:"Creciente-llena",precauciones:"No en plantines j\xF3venes."}],INTERMAREAL_PENCO=[{nombre:"Cochayuyo",cient:"Durvillaea antarctica",hab:"Roquer\xEDo expuesto, pozas bajas",icon:"\u{1F33F}",epoca:"Todo el a\xF1o \xB7 mejor bajamar",nota:"Alga parda gigante. Cosecha sostenible: corta frondas, no arranque ra\xEDz. Seca al sol para guardar."},{nombre:"Luche",cient:"Pyropia spp.",hab:"Rocas altas intermareal",icon:"\u{1F343}",epoca:"Jun\u2013Oct (invierno)",nota:"Alga roja fina, muy nutritiva. Solo en bajamar viva 0.3\u20130.5m. Enjuaga con agua de mar."},{nombre:"Huiro negro",cient:"Lessonia nigrescens",hab:"Roquer\xEDo bajo, pozas",icon:"\u{1F30A}",epoca:"Todo el a\xF1o",nota:"Forma bosques submareales. No extraer planta completa. Indicador de agua limpia."},{nombre:"Chorito",cient:"Mytilus chilensis",hab:"Rocas medias, colonias",icon:"\u{1F9AA}",epoca:"Todo el a\xF1o \xB7 veda vigilar",nota:"Talla m\xEDnima 5 cm. Solo 2\u20133 kg por familia. No en marea roja."},{nombre:"Choro zapato",cient:"Choromytilus chorus",hab:"Rocas bajas, submareal",icon:"\u{1F41A}",epoca:"Evitar en primavera si toxina",nota:"M\xE1s grande que chorito. Limpia agua, no saquear bancos."},{nombre:"Piure",cient:"Pyura chilensis",hab:"Roquer\xEDo bajo, pozas hondas",icon:"\u{1F534}",epoca:"Todo el a\xF1o",nota:"Tunicado rojo. Solo buceo apnea en bajamar. Corte limpio, deja base."},{nombre:"Lapa",cient:"Fissurella spp.",hab:"Roca expuesta, intermareal medio",icon:"\u{1F41A}",epoca:"Todo el a\xF1o",nota:"Talla 6 cm+. Una por roca, deja reproductores. Usa esp\xE1tula, no cuchillo."},{nombre:"Jaiba mora",cient:"Homalaspis plana",hab:"Pozas, bajo piedras",icon:"\u{1F980}",epoca:"Sep\u2013Mar",nota:"Hembras con huevos no se toman. Talla 12 cm. Devuelve peque\xF1as."},{nombre:"Erizo",cient:"Loxechinus albus",hab:"Roquer\xEDo bajo, submareal",icon:"\u{1F7E3}",epoca:"Veda variable (Sernapesca)",nota:"Veda frecuente. Consulta sernapesca.cl antes. No en luna llena (desove)."},{nombre:"Ulte (tallo cochayuyo)",cient:"Durvillaea antarctica",hab:"Base cochayuyo",icon:"\u{1F962}",epoca:"Todo el a\xF1o",nota:"Tallo comestible, crujiente. Pelar y picar, ensalada o escabeche."},{nombre:"Caracol trumulco",cient:"Chorus giganteus",hab:"Fango, pozas",icon:"\u{1F40C}",epoca:"Veda (en recuperaci\xF3n)",nota:"En veda larga. Solo observar. Foto y registro, no extracci\xF3n."},{nombre:"Estrella de mar",cient:"Stichaster striatus",hab:"Pozas, rocas bajas",icon:"\u2B50",epoca:"Todo el a\xF1o",nota:"No tocar ni sacar del agua. Indicadora de salud. Solo foto."}],BOSQUE_NATIVO_PENCO=[{nombre:"Canelo",cient:"Drimys winteri",hab:"Quebradas h\xFAmedas, borde estero",icon:"\u{1F333}",epoca:"Flor Aug\u2013Oct",tipo:"\xC1rbol sagrado",semillas:"Dic\u2013Feb",nota:"\xC1rbol sagrado mapuche (foye). Corteza pimienta. No talar: esqueje en menguante oto\xF1al. Semilla en baya negra; recolecta fruto maduro Dic\u2013Feb y siembra inmediato (recalcitrante, no guardar seca)."},{nombre:"Boldo",cient:"Peumus boldus",hab:"Ladera, bosque escler\xF3filo",icon:"\u{1F343}",epoca:"Flor Jul\u2013Sep \xB7 Fruto Ene",tipo:"\xC1rbol medicinal",semillas:"Ene\u2013Feb",nota:"Hoja digestiva. Recolecta 3\u20134 hojas por rama, nunca defoliar. Semilla en drupa: cosecha fruto maduro Ene\u2013Feb, limpia pulpa y siembra oto\xF1o temprano."},{nombre:"Peumo",cient:"Cryptocarya alba",hab:"Bosque costero, cerros Penco",icon:"\u{1F534}",epoca:"Fruto Mar\u2013May",tipo:"\xC1rbol",semillas:"Mar\u2013May",nota:"Fruto rojo comestible cocido. Recalcitrante: recolecta ca\xEDdo Mar\u2013May y siembra directo en bolsa profunda sin demora (no deshidratar)."},{nombre:"Array\xE1n",cient:"Luma apiculata",hab:"Estero, humedal borde",icon:"\u{1F7E0}",epoca:"Flor Dic\u2013Ene \xB7 Fruto Feb",tipo:"\xC1rbol",semillas:"Feb\u2013Abr",nota:"Corteza canela. Madera dura. Flor mel\xEDfera. Baya negra Feb\u2013Abr: macera y siembra primavera, sombra parcial."},{nombre:"Quillay",cient:"Quillaja saponaria",hab:"Ladera asoleada",icon:"\u{1F33F}",epoca:"Flor Nov\u2013Ene",tipo:"\xC1rbol",semillas:"Dic\u2013Feb",nota:"Corteza con saponina. Mel\xEDfero clave. C\xE1psula estrellada seca Dic\u2013Feb: recoge antes que abra, guarda en papel y siembra primavera (previo remojo 24h)."},{nombre:"Mait\xE9n",cient:"Maytenus boaria",hab:"Pradera, cerco vivo",icon:"\u{1F332}",epoca:"Todo el a\xF1o",tipo:"\xC1rbol",semillas:"Ene\u2013Mar",nota:"Forraje, cerco. Crece r\xE1pido. C\xE1psula con arilo rojo Ene\u2013Mar: recolecta y siembra en alm\xE1cigo oto\xF1al."},{nombre:"Avellano",cient:"Gevuina avellana",hab:"Bosque templado, vega",icon:"\u{1F330}",epoca:"Flor Nov\u2013Ene \xB7 Avellana Mar\u2013May",tipo:"\xC1rbol",semillas:"Mar\u2013May",nota:"Nuez nativa. Cosecha avellana ca\xEDda Mar\u2013May, no vareo: siembra directa a 3 cm, estrato h\xFAmedo. Tostar solo las de consumo."},{nombre:"Lingue",cient:"Persea lingue",hab:"Quebrada, bosque laurifolio",icon:"\u{1F333}",epoca:"Vulnerable",tipo:"\xC1rbol",semillas:"Feb\u2013Abr",nota:"Madera valiosa en categor\xEDa vulnerable. Solo observar y proteger, no cortar. Baya Feb\u2013Abr: si logras recolectar, siembra inmediata (muy recalcitrante)."},{nombre:"Copihue",cient:"Lapageria rosea",hab:"Quebrada sombr\xEDa, quila",icon:"\u{1F33A}",epoca:"Flor Feb\u2013Jul",tipo:"Enredadera nacional",semillas:"Sep\u2013Nov",nota:"Flor nacional. Protegida por ley. No cortar. Baya Sep\u2013Nov: solo observar. Reproducci\xF3n por semilla fresca en laboratorio, no extraer del bosque."},{nombre:"Chupalla",cient:"Eryngium paniculatum",hab:"Roquer\xEDo, cerro costero",icon:"\u{1F335}",epoca:"Flor Dic\u2013Mar",tipo:"Hierba",semillas:"Feb\u2013Abr",nota:"Fibra para artesan\xEDa. Solo hojas externas, deja roseta. Semilla seca Feb\u2013Abr: cosecha cabezuela marr\xF3n, trilla suave."},{nombre:"Lloyin / Hongos",cient:"Ramaria, Amanita, Boletus",hab:"Suelo bosque oto\xF1al",icon:"\u{1F344}",epoca:"Abr\u2013Jun",tipo:"Hongo",semillas:"No aplica (esporas Abr\u2013Jun)",nota:"Solo recolecta si 100% seguro (loyo, changle). Lleva canasto aireado. Deja micelio. Propaga por esporas, no semillas."},{nombre:"Maqui",cient:"Aristotelia chilensis",hab:"Borde bosque, quebrada",icon:"\u{1FAD0}",epoca:"Fruto Dic\u2013Ene",tipo:"Arbusto",semillas:"Dic\u2013Ene",nota:"Superfruto. Cosecha con tijera Dic\u2013Ene, deja 30% para aves. Extrae semilla lavando pulpa; siembra primavera con estratificaci\xF3n fr\xEDa 30 d\xEDas."},{nombre:"Trihue / Laurel",cient:"Laurelia sempervirens",hab:"Quebrada h\xFAmeda, bosque laurifolio costero",icon:"\u{1F33F}",epoca:"Flor Nov\u2013Dic",tipo:"\xC1rbol laurifolio",semillas:"Ene\u2013Mar",nota:"Laurel chileno arom\xE1tico (trihue). Muy escaso en Penco: solo observar y proteger. Aquenio plumoso Ene\u2013Mar: colecta con malla antes que vuele, siembra inmediata (viabilidad corta)."},{nombre:"Naranjillo",cient:"Citronella mucronata",hab:"Ladera sombr\xEDa, bosque escler\xF3filo h\xFAmedo",icon:"\u{1F34B}",epoca:"Flor Nov\u2013Dic \xB7 Fruto Feb\u2013Mar",tipo:"\xC1rbol nativo",semillas:"Feb\u2013Abr",nota:"End\xE9mico vulnerable. Drupa negra Feb\u2013Abr para aves. Recolecta ca\xEDda, despulpa y siembra oto\xF1o en sombra h\xFAmeda (recalcitrante)."},{nombre:"Keule",cient:"Gomortega keule",hab:"Quebrada costera, bosque relicto B\xEDo-B\xEDo",icon:"\u{1F330}",epoca:"Fruto Mar\u2013May \xB7 En Peligro",tipo:"\xC1rbol end\xE9mico",semillas:"Mar\u2013May (con permiso CONAF)",nota:"End\xE9mico B\xEDo-B\xEDo\u2013Maule, en peligro cr\xEDtico Monumento Natural. Fruto amarillo Mar\u2013May. Protegido: solo observar/fotografiar. No recolectar sin autorizaci\xF3n; siembra de hueso inmediata tras despulpado."}],CONSEJOS_INTERMAREAL={PUKEM:{titulo:"Pukem \u2014 Invierno: marejadas, poco acceso",texto:"Marejadas fuertes, rocas resbalosas. Solo bajamares diurnas <0.5m y sin alerta SHOA. Lleva cuerda y nunca vayas solo. Es tiempo de observar, no de cosechar grande."},PEWU:{titulo:"Pew\xFC \u2014 Primavera: bajamares vivas",texto:"Lunas nueva/llena \u2192 mareas m\xE1s bajas, ventana larga. Ideal para luche y cochayuyo tierno. Respeta talla y deja reproductores. Lava en sitio, lleva bolsa de malla."},WALUNG:{titulo:"Wal\xFCng \u2014 Verano: pozas y sol",texto:"Sol fuerte + pozas calientes: lleva gorro, agua y bloqueador. Marea baja temprano (06\u201309h). Revisa marea roja (sernapesca.cl) antes de mariscar. No dejes basura."},RIMU:{titulo:"Rim\xFC \u2014 Oto\xF1o: cierre y preparaci\xF3n",texto:"\xDAltimas bajamares buenas antes de invierno. Cosecha ulte/cochayuyo para guardar seco. Revisa bancos: si ves menos, no coseches esa poza el pr\xF3ximo ciclo."}},CONSEJOS_BOSQUE={PUKEM:{titulo:"Pukem \u2014 Invierno: lluvia y suelo",texto:"Suelo blando: planta nativo (peumo, quillay, canelo) esta luna. No entres con suelo barroso profundo (compactas). Junta semillas ca\xEDdas y gu\xE1rdalas en papel, no pl\xE1stico."},PEWU:{titulo:"Pew\xFC \u2014 Primavera: brotes y flores",texto:"Floraci\xF3n de boldo/canelo. No cortes flores. C\xE1mara y libreta. Es momento de esquejes semile\xF1osos y de eliminar eucalipto/pino invasor en d\xEDa menguante."},WALUNG:{titulo:"Wal\xFCng \u2014 Verano: fruto y sombra",texto:"Cosecha maqui, avellana, array\xE1n. Solo fruto maduro ca\xEDdo o con tijera. Lleva agua, no hagas fuego. Observa aves que dispersan semillas."},RIMU:{titulo:"Rim\xFC \u2014 Oto\xF1o: siembra y hongos",texto:"Mejor siembra directa de nativo (peumo, avellano) ni bien cae semilla. Hongos: cesta aireada, corta pie con cuchillo, deja micelio. No arranques todo."}};window.pencoData={PENCO,ESTACIONES,MOONS,DFT,INTRO,MOODS,EFEMERIDES,SIEMBRA,SIEMBRA_LUNAS,DONATE,AVES_PENCO,EVENTOS_ASTRONOMICOS,EVENTOS_COMUNA_PENCO,ASOCIACIONES_CULTIVOS,PREPARADOS_ORGANICOS,INTERMAREAL_PENCO,BOSQUE_NATIVO_PENCO,CONSEJOS_INTERMAREAL,CONSEJOS_BOSQUE};
